// DeviceIcon returns an inline SVG for a device: the entity's own mdi icon
// when it is one we ship, else the domain's glyph, else a generic switch.
func DeviceIcon(domain, haIcon string) string {
	d, ok := deviceMdiGlyphs[haIcon]
	if !ok {
		d, ok = deviceDomainGlyphs[domain]
	}
	if !ok {
		d = deviceDomainGlyphs["switch"]
	}
	return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="` + html.EscapeString(d) + `"/></svg>`
}
